const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name] || paths.bag}</svg>`;
const e = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = value => new Intl.NumberFormat('vi-VN').format(Number(value)||0)+'₫';
const compact = value => value>=1000 ? (value/1000).toFixed(1).replace('.0','')+'k' : String(value||0);
const nameOf = name => (name||'').replace(/\s*\(Model #\d+\)/g,'').replace(/\s*\(#\d+\)/g,'');
const shortProvince = name => (name||'Việt Nam').replace('Thành phố Hồ Chí Minh','TP. Hồ Chí Minh').replace('Thành phố ','');
const date = value => new Date(String(value).includes('T') ? value : value+'Z').toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',hour:'2-digit',minute:'2-digit',day:'2-digit',month:'2-digit',year:'numeric'});
const $ = selector => document.querySelector(selector);
const state = {user:null,demo:false,profiles:[],categories:[],provinces:[],wishlist:new Set(),cart:[],notices:[],
  debug:localStorage.getItem('muse_debug')==='true',debugInfo:null,recommendations:null,products:null,route:'home',
  routeVersion:0,modalVersion:0,authMode:'login',selectedProduct:null,quantity:1,checkout:{address_id:null,voucher_code:'',use_coins:false,payment_method:'COD'},
  checkoutKey:null,quote:null,quoteVersion:0,busy:false,orderTab:'Tất cả',hero:0,homeLimit:24};

async function api(path,options={}) {
  const response=await fetch('/api'+path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});
  let data;try{data=await response.json();}catch{throw new Error('Kết nối bị gián đoạn. Vui lòng thử lại.');}
  if(!response.ok) {
    const detail=data.detail;
    const message=typeof detail==='string'?detail:Array.isArray(detail)?detail.map(x=>x.loc.at(-1)+': '+x.msg).join('; '):'Có lỗi xảy ra. Vui lòng thử lại.';
    const error=new Error(message);error.status=response.status;throw error;
  }
  return data;
}
const post=(path,data={})=>api(path,{method:'POST',body:JSON.stringify(data)});
const put=(path,data={})=>api(path,{method:'PUT',body:JSON.stringify(data)});
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('#toasts').append(el);setTimeout(()=>el.remove(),4200);}
function updateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon);el.removeAttribute('data-icon');});}
function placeholder(root=document){root.querySelectorAll('img').forEach(img=>{img.addEventListener('error',()=>{if(!img.src.endsWith('/placeholder.svg'))img.src='/static/images/placeholder.svg';},{once:true});});}
function hydrate(){updateIcons();placeholder();document.querySelectorAll('.mobile-nav button').forEach(b=>b.classList.toggle('active',b.dataset.action===state.route));}
function appHTML(html){$('#app').innerHTML=html;hydrate();}
function empty(title,text,action='home',label='Khám phá ngay',symbol='bag'){return `<div class="empty-state">${icon(symbol)}<h3>${e(title)}</h3><p>${e(text)}</p><button class="primary" data-action="${action}">${e(label)} ${icon('arrow')}</button></div>`;}
function breadcrumb(title){return `<div class="breadcrumb"><button data-action="home">Trang chủ</button><span>›</span><span>${e(title)}</span></div>`;}
function openModal(title,html,small=false){const modal=$('#modal');modal.classList.toggle('modal-small',small);$('#modal-content').innerHTML=`<div class="modal-header"><h2 id="modal-title">${e(title)}</h2><button class="close-button" data-action="close-modal" aria-label="Đóng">${icon('close')}</button></div><div class="modal-body">${html}</div>`;if(!modal.open)modal.showModal();hydrate();}
function closeModal(){state.modalVersion++;$('#modal').close();}
function requireLogin(){if(state.user)return true;openAuth();return false;}
function navigate(route,params={}){closeModal();const query=new URLSearchParams(params).toString();const next='#/'+route+(query?'?'+query:'');if(location.hash===next)renderRoute();else location.hash=next;}
function routeParams(){return new URLSearchParams(location.hash.split('?')[1]||'');}
function refreshHeader(){
  $('#account-nav').innerHTML=icon('user')+e(state.user?nameOf(state.user.full_name):'Đăng nhập');
  $('#cart-count').textContent=state.cart.reduce((n,x)=>n+x.quantity,0);
  const count=state.notices.filter(n=>!n.is_read).length;$('#notice-count').textContent=count;$('#notice-count').hidden=!count;
  $('#demo-strip').hidden=!state.demo;$('#demo-toolbar').hidden=!state.demo;
  $('#debug-toggle').checked=state.debug;$('#profile-switch').value=state.user&&state.profiles.some(p=>p.id===state.user.id)?state.user.id:'';
}
async function refreshUser(){
  const current=await api('/auth/me');state.user=current.user;state.demo=current.demo_mode;
  if(state.user){const results=await Promise.all([api('/cart'),api('/account/notifications'),api('/account/wishlist')]);state.cart=results[0].items;state.notices=results[1];state.wishlist=new Set(results[2].map(x=>x.id));}
  else{state.cart=[];state.notices=[];state.wishlist=new Set();}
  refreshHeader();
}
async function refreshDebug(meta){
  const panel=$('#debug-panel');panel.hidden=!(state.debug&&state.demo);
  if(panel.hidden)return;
  if(!state.user){panel.innerHTML='<div class="container">MUSE Lab / Chọn một hồ sơ demo để xem chuỗi hành vi và kết quả suy luận.</div>';return;}
  try{
    const info=await api('/recommendations/debug');state.debugInfo=info;
    const m=meta||state.recommendations?.meta||{};
    panel.innerHTML=`<div class="container"><div class="debug-top"><strong>● MUSE INFERENCE CONSOLE <span class="badge">${info.ready?'CHECKPOINT LOADED':'FALLBACK'}</span></strong><button data-action="history">${icon('code')} Soi lịch sử chuỗi 1K</button></div><div class="debug-metrics"><div><span>ACTIVE USER / RAW TAOBAO ID</span>#${e(info.user_id)} / ${e(info.raw_user_id||'Cold start')}</div><div><span>HISTORY / GSU</span>${e(m.history_length??Math.min(info.history_count,1000))} hành vi · top-${e(info.gsu_top_k||'—')}</div><div><span>INFERENCE / SERVICE</span>${e(m.inference_ms??'—')} ms / ${e(m.latency_ms??'—')} ms</div><div><span>CANDIDATES / SCL COVERAGE</span>${e(m.candidate_count??'—')} / ${m.scl_coverage!=null?Math.round(m.scl_coverage*100)+'%':'—'}</div><div><span>ENGINE</span>${e(m.engine||info.engine)}</div></div><p class="debug-note">${e(m.strategy||'GSU → SimTier + SA-TA → ESU')} · SCL 128D · Raw ID được giữ dạng chuỗi 64-bit. AUC 0.644728 / GAUC 0.614794 là số liệu bạn cung cấp, chưa được web đánh giá lại.</p><p class="debug-note">Tên tiếng Việt, ngành hàng, giá và ảnh là dữ liệu thương mại minh họa; không phải metadata gốc Taobao. ${info.error?e(info.error):''}</p></div>`;hydrate();
  }catch(err){panel.textContent=err.message;}
}
function productCard(p){
  const score=state.debug&&state.demo?`<div class="product-score">${p.p_click!=null?'P(click): '+(p.p_click*100).toFixed(2)+'%':p.similarity!=null?'Cosine: '+p.similarity.toFixed(4):'Score: popularity'}<br>Raw: ${e(p.raw_item_id)}</div>`:'';
  return `<article class="product-card"><button class="heart-button ${state.wishlist.has(p.id)?'saved':''}" data-action="favorite" data-id="${p.id}" aria-label="${state.wishlist.has(p.id)?'Bỏ yêu thích':'Yêu thích sản phẩm'}">${icon('heart')}</button><button class="product-card-main" data-action="product" data-id="${p.id}"><div class="product-image"><img loading="lazy" src="${e(p.image_url)}" alt="${e(nameOf(p.name))}">${p.is_mall?'<span class="mall-tag">Mall</span>':''}<span class="discount">−${e(p.discount_percent)}%</span></div><div class="product-info"><h3 class="product-name">${e(nameOf(p.name))}</h3><div class="product-promos">${p.is_freeship?'<span class="free-tag">Freeship Xtra</span>':''}<span>Giá tốt mỗi ngày</span></div><div class="product-prices"><span class="price"><small>₫</small>${money(p.price).replace('₫','')}</span><span class="old-price">${compact(p.original_price)}</span></div><div class="product-meta"><span><span class="stars">★</span> ${e(p.rating_star)}</span><span>Đã bán ${compact(p.sold_count)}</span></div><div class="product-location">${icon('pin')}${e(shortProvince(p.province_name))}</div></div>${score}</button></article>`;
}
function productGrid(items){return `<div class="product-grid">${items.map(productCard).join('')}</div>`;}
