function heroHTML(){const h=heroes[state.hero];return `<div class="hero-copy"><div class="eyebrow">${h.eye}</div><h1>${h.title}</h1><p>${h.copy}</p><button class="primary" data-search="${e(h.search)}">${h.button} ${icon('arrow')}</button></div><div class="hero-art"><div class="hero-circle"></div><img src="${h.img}" alt="Cảm hứng mua sắm"><div class="hero-sticker">${h.sticker}<b>${h.amount}</b></div></div><div class="hero-pagination">${heroes.map((_,i)=>`<button class="${i===state.hero?'active':''}" data-action="hero" data-index="${i}" aria-label="Ưu đãi ${i+1}"></button>`).join('')}</div>`;}
async function renderHome(version){
  appHTML(`<div class="container page"><div class="welcome-line"><span>${icon('sparkles')} ${state.user?`Chào ${e(nameOf(state.user.full_name).split(' ').slice(-1))}, <b>hôm nay bạn muốn tìm gì?</b>`:'Mỗi ngày một khám phá. <b>Mỗi lựa chọn đều là bạn.</b>'}</span><small>CHỌN ĐIỀU BẠN YÊU · MUA ĐIỀU BẠN THÍCH</small></div><div class="hero-layout"><section class="hero" id="hero">${heroHTML()}</section><div class="side-promos"><article class="promo promo-one"><div><small>HOME, SWEET HOME</small><h3>Chút mới mẻ.<br>Nhiều an yên.</h3><p>Góc nhà nhỏ, cảm hứng lớn.</p><button data-category="6">Khám phá ${icon('arrow')}</button></div><img src="/static/images/catalog/1d2b90e9593ea950.jpg" alt="Cà phê cho không gian sống"></article><article class="promo promo-two"><div><small>LOVE YOUR EVERYDAY</small><h3>Đẹp theo cách<br>của riêng bạn.</h3><p>Chăm chút những điều nhỏ.</p><button data-category="7">Yêu chiều bản thân ${icon('arrow')}</button></div><img src="/static/images/catalog/42b2f8a7cabd17ed.jpg" alt="Chăm sóc da mỗi ngày"></article></div></div><div class="benefit-strip"><div class="benefit">${icon('truck')}<div><strong>Miễn phí vận chuyển</strong><small>Đơn đủ điều kiện từ 150.000₫</small></div></div><div class="benefit">${icon('shield')}<div><strong>Yên tâm mua sắm</strong><small>Thông tin đơn hàng minh bạch</small></div></div><div class="benefit">${icon('ticket')}<div><strong>Ưu đãi mỗi ngày</strong><small>Voucher dành riêng cho bạn</small></div></div><div class="benefit">${icon('sparkles')}<div><strong>Khám phá đúng gu</strong><small>Gợi ý cá nhân hóa thông minh</small></div></div></div><section class="section"><div class="section-title"><h2>Điều bạn đang tìm</h2><button data-action="catalog">Tất cả danh mục ${icon('arrow')}</button></div><div class="category-list">${state.categories.map((c,i)=>`<button class="category" data-category="${c.id}"><span class="category-icon">${icon(categoryIcons[i])}</span><span>${categoryNames[i]}</span><small>${c.product_count} sản phẩm</small></button>`).join('')}</div></section><div class="quick-vouchers"><button class="mini-voucher" data-action="vouchers">${icon('truck')}<span><strong>Freeship đến 50.000₫</strong><small>Lưu mã, thêm niềm vui mua sắm</small></span><span>›</span></button><button class="mini-voucher" data-action="vouchers">${icon('ticket')}<span><strong>Voucher giảm đến 20%</strong><small>Ưu đãi công nghệ AI MUSE</small></span><span>›</span></button><button class="mini-voucher" data-action="vouchers">${icon('bag')}<span><strong>Chào bạn mới · Giảm 30k</strong><small>Khởi đầu nhỏ, ưu đãi lớn</small></span><span>›</span></button></div><section class="section flash"><div class="section-title"><div class="flash-heading"><h2>FLASH SALE</h2><div class="countdown" id="countdown" aria-label="Đếm ngược ưu đãi"></div></div><button data-action="flash">Xem ưu đãi ${icon('arrow')}</button></div><div class="flash-grid" id="flash-grid"></div></section><section class="section muse-banner"><div class="muse-symbol">${icon('sparkles')}</div><div class="muse-banner-copy"><div class="eyebrow">A LITTLE INTELLIGENCE. A LOT MORE YOU.</div><h3>Không chỉ là gợi ý. Là hiểu bạn hơn.</h3><p>Khám phá những món đồ phù hợp từ lịch sử mua sắm của chính bạn.</p></div><button data-action="muse-info">Cùng khám phá MUSE ${icon('arrow')}</button></section><section class="section" id="discovery"><div class="section-title recommend-title"><div><h2>Gợi ý hôm nay <span class="badge">DÀNH RIÊNG CHO BẠN</span></h2><p>${state.user?'Lựa chọn mới từ những điều bạn đã quan tâm.':'Đăng nhập để khám phá gợi ý theo sở thích của bạn.'}</p></div><div class="recommend-status"><span class="status-dot"></span> Được chọn cho bạn</div></div><div id="home-products"><div class="skeleton-grid">${Array(6).fill('<div class="skeleton"></div>').join('')}</div></div><div class="load-more"><button data-action="home-more">Khám phá thêm ${icon('arrow')}</button></div></section></div>`);
  updateCountdown();
  const [flash,recs]=await Promise.all([api('/products?sort=discount&page_size=6'),api('/recommendations?limit='+state.homeLimit)]);
  if(version!==state.routeVersion)return;
  $('#flash-grid').innerHTML=flash.items.map((p,i)=>`<article class="flash-card"><button class="product-card-main" data-action="product" data-id="${p.id}" aria-label="${e(nameOf(p.name))}"><div class="flash-img"><img loading="lazy" src="${e(p.image_url)}" alt="${e(nameOf(p.name))}"><span class="discount">−${p.discount_percent}%</span></div><strong class="price">${money(p.price)}</strong><div class="sale-progress" style="--progress:${65+i*4}%"><span>ĐÃ BÁN ${compact(p.sold_count)}</span></div></button></article>`).join('');
  state.recommendations=recs;$('#home-products').innerHTML=productGrid(recs.items);hydrate();refreshDebug(recs.meta);
}
function updateCountdown(){const el=$('#countdown');if(!el)return;const now=new Date();const next=new Date(now);next.setUTCHours(17,0,0,0);if(next<=now)next.setUTCDate(next.getUTCDate()+1);const seconds=Math.floor((next-now)/1000);const parts=[Math.floor(seconds/3600),Math.floor(seconds%3600/60),seconds%60];el.innerHTML=parts.map(x=>'<b>'+String(x).padStart(2,'0')+'</b>').join('<span>:</span>');}
async function renderCatalog(version){
  const params=routeParams();const category=Number(params.get('category_id'));const q=params.get('q')||'';
  const title=q?`Kết quả cho “${q}”`:category?categoryNames[category-1]:'Khám phá sản phẩm';
  const sort=params.get('sort')||'popular';const page=Number(params.get('page')||1);
  appHTML(`<div class="container page">${breadcrumb(title)}<h1 class="page-title">${e(title)}</h1><p class="page-subtitle">Tìm món đồ phù hợp, theo cách của bạn.</p><div class="catalog-layout"><aside class="filter-panel"><h3>${icon('filter')} Bộ lọc tìm kiếm</h3><div class="filter-categories"><button data-action="catalog" class="${!category?'active':''}">Tất cả sản phẩm</button>${state.categories.map((c,i)=>`<button data-category="${c.id}" class="${category===c.id?'active':''}">${categoryNames[i]}</button>`).join('')}</div><form id="filter-form"><div class="filter-group"><label>Khoảng giá (₫)</label><input type="number" name="min_price" min="0" placeholder="Từ" aria-label="Giá từ" value="${e(params.get('min_price')||'')}"><input type="number" name="max_price" min="0" placeholder="Đến" aria-label="Giá đến" value="${e(params.get('max_price')||'')}"></div><div class="filter-group"><label for="province-filter">Nơi bán</label><select id="province-filter" name="province_id"><option value="">Tất cả tỉnh thành</option>${provinceOptions(params.get('province_id'))}</select><button class="primary" type="submit">Áp dụng bộ lọc</button></div></form><button class="auth-link" data-action="clear-filter">Xóa bộ lọc</button></aside><div><div class="sort-bar"><span>Sắp xếp theo</span>${[['popular','Phổ biến'],['newest','Mới nhất'],['sold','Bán chạy'],['discount','Ưu đãi']].map(([s,t])=>`<button class="${s===sort?'active':''}" data-sort="${s}">${t}</button>`).join('')}<select id="price-sort" aria-label="Sắp xếp theo giá"><option value="">Giá</option><option value="price_asc" ${sort==='price_asc'?'selected':''}>Thấp đến cao</option><option value="price_desc" ${sort==='price_desc'?'selected':''}>Cao đến thấp</option></select><small class="result-count" id="result-count"></small></div><div id="catalog-products"><div class="skeleton-grid">${Array(6).fill('<div class="skeleton"></div>').join('')}</div></div><div class="pagination" id="pagination"></div></div></div></div>`);
  const query=new URLSearchParams(params);query.set('page_size','24');
  const result=await api('/products?'+query);if(version!==state.routeVersion)return;state.products=result;
  $('#catalog-products').innerHTML=result.items.length?productGrid(result.items):empty('Chưa tìm thấy sản phẩm','Thử từ khóa khác hoặc điều chỉnh bộ lọc.','catalog','Xem tất cả sản phẩm','search');
  $('#result-count').textContent=result.total+' kết quả';
  const first=Math.max(1,Math.min(page-2,result.pages-4));const pages=Array.from({length:Math.min(5,result.pages)},(_,i)=>first+i);
  $('#pagination').innerHTML=result.pages>1?`<button data-page="${page-1}" ${page<=1?'disabled':''} aria-label="Trang trước">‹</button>${pages.map(p=>`<button data-page="${p}" class="${p===page?'active':''}">${p}</button>`).join('')}<button data-page="${page+1}" ${page>=result.pages?'disabled':''} aria-label="Trang sau">›</button>`:'';hydrate();
}
function updateCatalogParams(changes){const params=routeParams();for(const [key,value] of Object.entries(changes)){if(value==null||value==='')params.delete(key);else params.set(key,value);}if(!('page'in changes))params.delete('page');navigate('catalog',Object.fromEntries(params));}
function provinceOptions(selected){return state.provinces.map(p=>`<option value="${p.id}" ${Number(selected)===p.id?'selected':''}>${e(p.name)}</option>`).join('');}
async function openProduct(id){
  const version=++state.modalVersion;openModal('Chi tiết sản phẩm','<div class="loading-screen"><div class="spinner"></div></div>');
  const p=await api('/products/'+id);if(version!==state.modalVersion)return;state.selectedProduct=p;state.quantity=1;
  openModal('Khám phá sản phẩm',`<div class="product-detail"><div><div class="detail-image"><img src="${e(p.image_url)}" alt="${e(nameOf(p.name))}"></div><div class="detail-thumbs"><img src="${e(p.image_url)}" alt="Ảnh sản phẩm"></div></div><div><h1 class="detail-title">${p.is_mall?'<span class="badge">Mall</span>':''}${e(nameOf(p.name))}</h1><div class="detail-rating"><span class="stars">★ ${p.rating_star}</span><span>${compact(p.rating_count)} đánh giá mẫu</span><span>${compact(p.sold_count)} đã bán mẫu</span></div><div class="detail-pricing"><span class="old-price">${money(p.original_price)}</span><strong class="price">${money(p.price)}</strong><span class="badge">GIẢM ${p.discount_percent}%</span></div><div class="detail-line"><span>Ưu đãi</span><div><span class="badge">Freeship Xtra</span><p>Đơn từ 150.000₫ khi đủ điều kiện.</p></div></div><div class="detail-line"><span>Vận chuyển</span><div>${icon('truck')} Gửi từ ${e(shortProvince(p.province_name))}<p>Phí giao hàng được tính khi chọn địa chỉ.</p></div></div><div class="detail-line"><span>Số lượng</span><div><div class="quantity"><button data-action="detail-minus" aria-label="Giảm số lượng">−</button><input id="detail-quantity" type="number" min="1" max="${Math.min(p.stock,99)}" value="1" aria-label="Số lượng mua"><button data-action="detail-plus" aria-label="Tăng số lượng">+</button></div><p>${p.stock} sản phẩm có sẵn</p></div></div><div class="detail-actions"><button class="outline" data-action="add-product">${icon('cart')} Thêm vào giỏ hàng</button><button class="primary" data-action="buy-product">Mua ngay</button></div><div class="detail-guarantee">${icon('shield')} Kiểm tra thông tin và tổng tiền trước khi đặt hàng</div>${state.debug?`<div class="product-score">Raw Taobao item ID: ${e(p.raw_item_id)}<br>ID ảnh và thông tin thương mại được ánh xạ cho demo.</div>`:''}</div></div><div class="detail-shop"><div><strong>${e(p.shop_name)}</strong><small>Gian hàng minh họa · ${e(shortProvince(p.province_name))}</small></div><button class="soft-button" data-shop="${e(p.shop_name)}">Xem cửa hàng ${icon('arrow')}</button></div><div class="detail-description"><h3>Thông tin sản phẩm</h3><p>${e(p.description||`${nameOf(p.name)}. Vui lòng kiểm tra thông tin sản phẩm và số lượng trước khi đặt hàng. Sản phẩm thuộc danh mục ${p.category_name}.`)}</p><p>Mã sản phẩm: SP${String(p.id).padStart(5,'0')} · Tồn kho và giá được kiểm tra lại khi đặt hàng.</p></div><div class="detail-description"><h3>Đánh giá từ người mua (${p.reviews.length})</h3>${p.reviews.length?p.reviews.map(r=>`<p><span class="stars">${'★'.repeat(r.rating)}</span> ${e(nameOf(r.full_name))} · ${e(date(r.created_at))}<br>${e(r.content)}</p>`).join(''):'<p>Chưa có đánh giá mua hàng xác thực. Các chỉ số đánh giá trên danh mục là dữ liệu mẫu.</p>'}</div><section class="detail-similar"><h3>Sản phẩm tương tự cùng phong cách</h3><div id="similar-products"><div class="spinner"></div></div></section>`);
  if(state.user){await post('/recommendations/behavior/'+id);refreshHomeRecommendations().catch(()=>{});}
  const related=await api('/recommendations?touchpoint=similar&product_id='+id+'&limit=4');if(version!==state.modalVersion)return;
  const target=$('#similar-products');if(target){target.innerHTML=productGrid(related.items);hydrate();}refreshDebug(related.meta);
}
async function refreshHomeRecommendations(){
  if(state.route!=='home')return;const userId=state.user?.id;const version=state.routeVersion;
  const result=await api('/recommendations?limit='+state.homeLimit);if(version!==state.routeVersion||userId!==state.user?.id)return;
  state.recommendations=result;const target=$('#home-products');if(target){target.innerHTML=productGrid(result.items);hydrate();}await refreshDebug(result.meta);
}
async function addProduct(buy=false){
  if(!requireLogin())return;const p=state.selectedProduct;if(!p)return;
  const quantity=Number($('#detail-quantity')?.value||state.quantity);
  if(!Number.isInteger(quantity)||quantity<1||quantity>Math.min(p.stock,99))throw new Error('Vui lòng chọn số lượng hợp lệ.');
  await post('/cart',{product_id:p.id,quantity});await refreshUser();
  if(buy)navigate('cart');else{toast('Đã thêm sản phẩm vào giỏ hàng.');refreshHomeRecommendations().catch(()=>{});}
}
function accountSidebar(active){return `<aside class="account-sidebar"><div class="account-avatar">${state.user.avatar_url?`<img src="${e(state.user.avatar_url)}" alt="Ảnh đại diện">`:`<span class="avatar-letter">${e(nameOf(state.user.full_name).at(0))}</span>`}<div><strong>${e(nameOf(state.user.full_name))}</strong><small>Hạng ${e(state.user.member_tier)}</small></div></div>${[['account','user','Hồ sơ của tôi'],['orders','bag','Đơn mua'],['addresses','pin','Sổ địa chỉ'],['vouchers','ticket','Kho voucher'],['wishlist','heart','Đã yêu thích'],['notifications','bell','Thông báo'],['password','lock','Đổi mật khẩu'],['logout','logout','Đăng xuất']].map(([r,i,t])=>`<button class="${active===r?'active':''}" data-action="${r}">${icon(i)}${t}</button>`).join('')}</aside>`;}
