async function renderCart(version){
  const result=await api('/cart');if(version!==state.routeVersion)return;state.cart=result.items;refreshHeader();
  if(!state.cart.length){appHTML(`<div class="container page">${breadcrumb('Giỏ hàng')}<h1 class="page-title">Giỏ hàng của bạn</h1><p class="page-subtitle">Thêm một chút niềm vui vào ngày mới.</p>${empty('Giỏ hàng đang chờ bạn','Khám phá những món đồ phù hợp với sở thích của bạn.','catalog','Tiếp tục mua sắm','cart')}</div>`);return;}
  const groups=Object.groupBy?Object.groupBy(state.cart,x=>x.shop_name):state.cart.reduce((a,x)=>{(a[x.shop_name]??=[]).push(x);return a;},{});
  const remaining=Math.max(0,150000-result.subtotal);
  appHTML(`<div class="container page">${breadcrumb('Giỏ hàng')}<h1 class="page-title">Giỏ hàng của bạn <span class="badge">${result.count} SẢN PHẨM</span></h1><p class="page-subtitle">Những lựa chọn nhỏ. Niềm vui thật lớn.</p><div class="cart-layout"><div><div class="content-card" style="padding:0"><label class="cart-select-all"><input id="cart-select-all" type="checkbox" ${state.cart.every(x=>x.is_selected)?'checked':''}>Chọn tất cả (${state.cart.length})</label>${Object.entries(groups).map(([shop,items])=>`<div class="cart-shop"><span class="badge">Mall</span>${e(shop)}</div>${items.map(i=>`<article class="cart-line"><input type="checkbox" data-cart-select="${i.cart_item_id}" ${i.is_selected?'checked':''} aria-label="Chọn ${e(nameOf(i.name))}"><img src="${e(i.image_url)}" alt="${e(nameOf(i.name))}"><div><button data-action="product" data-id="${i.id}"><h3>${e(nameOf(i.name))}</h3></button><p>Kho: ${e(shortProvince(i.province_name))}</p></div><strong class="price">${money(i.price)}</strong><div class="quantity"><button data-action="cart-minus" data-id="${i.cart_item_id}" ${i.quantity<=1?'disabled':''} aria-label="Giảm số lượng">−</button><span>${i.quantity}</span><button data-action="cart-plus" data-id="${i.cart_item_id}" aria-label="Tăng số lượng">+</button></div><button class="remove-button" data-action="cart-remove" data-id="${i.cart_item_id}" aria-label="Xóa sản phẩm">${icon('trash')}</button></article>`).join('')}`).join('')}</div><div class="shipping-progress">${remaining?'Mua thêm '+money(remaining)+' để đạt mốc ưu đãi vận chuyển.':'Bạn đã đạt mốc ưu đãi vận chuyển 150.000₫.'}<div><span style="--progress:${Math.min(100,result.subtotal/1500)}%"></span></div></div><section class="section"><div class="section-title"><div><h2>Mua kèm, thêm niềm vui</h2><p>Gợi ý theo giá và sở thích. Điều kiện vận chuyển tính tại thanh toán.</p></div></div><div id="cart-recommendations"><div class="spinner"></div></div></section></div><aside class="content-card checkout-summary"><h3>Tóm tắt giỏ hàng</h3><div class="summary-row"><span>Tiền hàng đã chọn</span><strong>${money(result.subtotal)}</strong></div><div class="summary-row"><span>Vận chuyển & ưu đãi</span><strong>Tính ở bước sau</strong></div><div class="summary-row total"><span>Tạm tính</span><strong>${money(result.subtotal)}</strong></div><button class="primary" data-action="checkout" ${!result.subtotal?'disabled':''}>Mua hàng ${icon('arrow')}</button><small>Chỉ thanh toán các sản phẩm đã chọn.</small></aside></div></div>`);
  const recs=await api('/recommendations?touchpoint=cart&limit=6');if(version!==state.routeVersion)return;$('#cart-recommendations').innerHTML=productGrid(recs.items);hydrate();refreshDebug(recs.meta);
}
function summaryHTML(bill){return `<div class="summary-row"><span>Tổng tiền hàng</span><strong>${money(bill.subtotal)}</strong></div><div class="summary-row"><span>Phí vận chuyển (${bill.shop_count} shop)</span><strong>${money(bill.shipping_fee)}</strong></div>${bill.shipping_discount?`<div class="summary-row discount-row"><span>Ưu đãi vận chuyển</span><strong>−${money(bill.shipping_discount)}</strong></div>`:''}${bill.voucher_discount?`<div class="summary-row discount-row"><span>Voucher giảm giá</span><strong>−${money(bill.voucher_discount)}</strong></div>`:''}${bill.coin_discount?`<div class="summary-row discount-row"><span>Shopee Xu</span><strong>−${money(bill.coin_discount)}</strong></div>`:''}<div class="summary-row total"><span>Tổng thanh toán</span><strong>${money(bill.total)}</strong></div>`;}
async function renderCheckout(version){
  const [addresses,vouchers,cart]=await Promise.all([api('/account/addresses'),api('/vouchers'),api('/cart')]);if(version!==state.routeVersion)return;
  if(!cart.items.some(x=>x.is_selected)){navigate('cart');return;}
  if(!addresses.some(a=>a.id===state.checkout.address_id))state.checkout.address_id=addresses.find(a=>a.is_default)?.id||addresses[0]?.id||null;
  const available=vouchers.filter(v=>v.status==='available');if(!available.some(v=>v.code===state.checkout.voucher_code))state.checkout.voucher_code='';
  state.quote=null;state.checkoutKey=state.checkoutKey||crypto.randomUUID();
  appHTML(`<div class="container page">${breadcrumb('Thanh toán')}<h1 class="page-title">Chỉ một bước nữa thôi.</h1><p class="page-subtitle">Kiểm tra thông tin và chờ đón món đồ yêu thích.</p>${state.demo?'<div class="alert">Đây là đơn hàng demo. Ví ShopeePay và quá trình giao hàng được mô phỏng; không phát sinh thanh toán thật.</div>':''}<div class="cart-layout"><div><section class="content-card checkout-section"><h3>${icon('pin')} Địa chỉ nhận hàng</h3>${addresses.length?addresses.map(a=>`<label class="address-option"><input type="radio" name="checkout_address" value="${a.id}" ${state.checkout.address_id===a.id?'checked':''}><div><strong>${e(a.recipient_name)} · ${e(a.phone)}</strong><p>${e(a.detail)}, ${e(a.province_name)}</p>${a.is_default?'<span class="default-tag">Mặc định</span>':''}</div></label>`).join(''):'<p class="page-subtitle">Bạn chưa có địa chỉ nhận hàng.</p>'}<button class="auth-link" data-action="new-address">+ Thêm địa chỉ mới</button></section><section class="content-card checkout-section"><h3>${icon('bag')} Sản phẩm đã chọn</h3>${cart.items.filter(i=>i.is_selected).map(i=>`<div class="order-item"><img src="${e(i.image_url)}" alt="${e(nameOf(i.name))}"><div>${e(nameOf(i.name))}<p>${e(i.shop_name)} · x${i.quantity}</p></div><span>${money(i.price*i.quantity)}</span></div>`).join('')}</section><section class="content-card checkout-section"><h3>${icon('ticket')} Ưu đãi của bạn</h3><select id="checkout-voucher" aria-label="Chọn voucher"><option value="">Không dùng voucher</option>${available.map(v=>`<option value="${e(v.code)}" ${state.checkout.voucher_code===v.code?'selected':''}>${e(v.code)} · ${e(v.title)} (từ ${money(v.min_order_value)})</option>`).join('')}</select><label class="coin-option"><input id="checkout-coins" type="checkbox" ${state.checkout.use_coins?'checked':''} ${!state.user.shopee_coins?'disabled':''}> Dùng tối đa ${money(Math.min(state.user.shopee_coins,25000))} từ ${compact(state.user.shopee_coins)} Shopee Xu</label><button class="auth-link" data-action="vouchers">Xem kho voucher để lưu thêm ưu đãi</button></section><section class="content-card checkout-section"><h3>${icon('shield')} Phương thức thanh toán</h3><label class="address-option"><input name="payment" type="radio" value="COD" ${state.checkout.payment_method==='COD'?'checked':''}><div><strong>Thanh toán khi nhận hàng (COD)</strong><p>Thanh toán cho đơn vị vận chuyển khi nhận hàng.</p></div></label>${state.demo?`<label class="address-option"><input name="payment" type="radio" value="ShopeePay" ${state.checkout.payment_method==='ShopeePay'?'checked':''}><div><strong>Ví ShopeePay · DEMO</strong><p>Số dư mô phỏng: ${money(state.user.wallet_balance)}</p></div></label>`:''}</section></div><aside class="content-card checkout-summary"><h3>Chi tiết thanh toán</h3><div id="checkout-bill"><p class="page-subtitle">${addresses.length?'Đang tính tổng tiền…':'Thêm địa chỉ để xem tổng thanh toán.'}</p></div><p class="error-text" id="checkout-error"></p><button class="primary" id="place-order" data-action="place-order" disabled>Đặt hàng ngay ${icon('arrow')}</button><small>Giá, tồn kho và ưu đãi được kiểm tra lại tại server.</small></aside></div></div>`);
  if(addresses.length)await updateQuote();
}
async function updateQuote(){
  const version=++state.quoteVersion;state.quote=null;const button=$('#place-order');if(button)button.disabled=true;
  if(!state.checkout.address_id)return;
  try{const bill=await post('/checkout/quote',state.checkout);if(version!==state.quoteVersion||state.route!=='checkout')return;state.quote=bill;$('#checkout-bill').innerHTML=summaryHTML(bill);$('#checkout-error').textContent='';$('#place-order').disabled=false;}
  catch(error){if(version!==state.quoteVersion||state.route!=='checkout')return;$('#checkout-error').textContent=error.message;}
}
async function placeOrder(){
  if(state.busy||!state.quote)return;state.busy=true;const button=$('#place-order');button.disabled=true;button.textContent='Đang đặt hàng…';
  try{const order=await post('/orders',{...state.checkout,idempotency_key:state.checkoutKey,expected_total:state.quote.total});state.checkoutKey=null;state.checkout.voucher_code='';state.checkout.use_coins=false;await refreshUser();closeModal();state.route='success';appHTML(`<div class="container page"><div class="content-card success-state">${icon('check')}<h1>Đặt hàng thành công!</h1><p>Cảm ơn bạn. Những lựa chọn mới đang trên đường đến với bạn.</p><div class="success-code">${e(order.order_code)}</div><p>Tổng thanh toán: <strong>${money(order.final_payment_amount)}</strong></p><p>Đơn hàng đang chờ xác nhận ${state.demo?'· Giao dịch mô phỏng':''}</p><button class="primary" data-action="orders">Theo dõi đơn hàng ${icon('arrow')}</button><button class="auth-link" data-action="home">Tiếp tục mua sắm</button></div></div>`);window.scrollTo({top:0,behavior:'smooth'});}
  catch(error){toast(error.message,true);if(error.status===409){state.checkoutKey=crypto.randomUUID();await updateQuote();}else if($('#place-order')){$('#place-order').disabled=false;$('#place-order').innerHTML='Thử đặt hàng lại '+icon('arrow');}}
  finally{state.busy=false;}
}
function openAuth(mode='login'){
  state.authMode=mode;
  const titles={login:'Chào bạn, mừng bạn trở lại.',register:'Bắt đầu hành trình của bạn.',forgot:'Tìm lại tài khoản của bạn.',reset:'Tạo mật khẩu mới.'};
  let fields='';
  if(mode==='register')fields+=`<div class="field"><label for="auth-name">Họ và tên</label><input id="auth-name" name="full_name" required minlength="2" maxlength="100" autocomplete="name"></div><div class="field"><label for="auth-phone">Số điện thoại</label><input id="auth-phone" name="phone" required pattern="0[0-9]{9}" inputmode="tel" autocomplete="tel"></div>`;
  if(mode!=='reset')fields+=`<div class="field"><label for="auth-email">Email</label><input id="auth-email" name="email" type="email" required maxlength="254" autocomplete="email"></div>`;
  if(mode==='reset')fields+=`<div class="alert">Mã OTP demo: <strong>888999</strong> · Hiệu lực 5 phút, tối đa 5 lần thử.</div><div class="field"><label for="auth-code">Mã OTP</label><input id="auth-code" name="code" required inputmode="numeric" pattern="[0-9]{6}" autocomplete="one-time-code"></div>`;
  if(mode!=='forgot')fields+=`<div class="field"><label for="auth-password">${mode==='reset'?'Mật khẩu mới':'Mật khẩu'}</label><input id="auth-password" name="password" type="password" required minlength="${mode==='login'?1:8}" maxlength="128" autocomplete="${mode==='login'?'current-password':'new-password'}"></div>`;
  const profiles=state.demo&&(mode==='login'||mode==='register')?`<div class="demo-auth"><p>TRẢI NGHIỆM NHANH · 8 HỒ SƠ TAOBAO-MM</p><div class="demo-profile-grid">${state.profiles.map(p=>`<button data-action="demo-login" data-id="${p.id}">${p.avatar_url?`<img src="${e(p.avatar_url)}" alt="">`:''}${e(nameOf(p.full_name))}</button>`).join('')}</div></div>`:'';
  openModal(titles[mode],`${mode==='login'||mode==='register'?`<div class="auth-tabs"><button data-auth="login" class="${mode==='login'?'active':''}">Đăng nhập</button><button data-auth="register" class="${mode==='register'?'active':''}">Đăng ký</button></div>`:''}<form id="auth-form" class="auth-form">${fields}<p class="error-text" id="form-error"></p><button class="primary" type="submit">${{login:'Đăng nhập',register:'Tạo tài khoản',forgot:'Gửi mã khôi phục',reset:'Đặt lại mật khẩu'}[mode]}</button>${mode==='login'?'<button class="auth-link" type="button" data-auth="forgot">Quên mật khẩu?</button>':''}${mode==='forgot'||mode==='reset'?'<button class="auth-link" type="button" data-auth="login">Quay lại đăng nhập</button>':''}</form>${profiles}`,true);
}
async function loginDemo(id){await post('/auth/demo-login',{user_id:Number(id)});state.checkout={address_id:null,voucher_code:'',use_coins:false,payment_method:'COD'};state.checkoutKey=null;state.recommendations=null;await refreshUser();closeModal();toast('Đã chuyển hồ sơ: '+nameOf(state.user.full_name));await renderRoute();}
async function renderRoute(){
  const route=(location.hash.replace(/^#\//,'').split('?')[0]||'home');state.route=route;const version=++state.routeVersion;window.scrollTo(0,0);
  if(['account','orders','addresses','vouchers','wishlist','notifications','password','cart','checkout'].includes(route)&&!state.user){appHTML(`<div class="container page">${empty('Mua sắm dành riêng cho bạn','Đăng nhập để lưu lựa chọn và tiếp tục mua sắm.','login','Đăng nhập ngay','user')}</div>`);openAuth();return;}
  if(route!=='home'&&route!=='catalog')appHTML('<div class="container loading-screen"><div class="spinner"></div><p>Đang tải…</p></div>');
  try{switch(route){case'home':await renderHome(version);break;case'catalog':await renderCatalog(version);break;case'account':await renderAccount();break;case'addresses':await renderAddresses(version);break;case'vouchers':await renderVouchers(version);break;case'wishlist':await renderWishlist(version);break;case'notifications':await renderNotifications(version);break;case'orders':await renderOrders(version);break;case'password':renderPassword();break;case'cart':await renderCart(version);break;case'checkout':await renderCheckout(version);break;default:navigate('home');}}
  catch(error){if(version===state.routeVersion)appHTML(`<div class="container page">${empty('Chưa tải được nội dung',error.message,'retry','Thử lại','return')}</div>`);}
  hydrate();refreshDebug();
}
async function confirmAction(title,text,action,id){openModal(title,`<p class="page-subtitle">${e(text)}</p><button class="primary" data-action="${action}" data-id="${id}">Xác nhận</button><button class="soft-button" data-action="close-modal">Quay lại</button>`,true);}
function museInfo(){openModal('Một chút AI. Thêm nhiều điều hợp gu.',`<div class="help-prose"><h3>Gợi ý từ hành trình của bạn</h3><p>Alibaba MUSE kết hợp ID sản phẩm và vector đa phương thức SCL 128 chiều. GSU chọn các hành vi gần với sản phẩm ứng viên trong lịch sử dài hạn; SimTier và SA-TA tổng hợp tín hiệu để dự đoán xác suất click.</p><h3>Ba điểm chạm</h3><p>Trang chủ xếp hạng ứng viên theo người dùng. Chi tiết sản phẩm tìm tương đồng bằng SCL cosine. Giỏ hàng chọn gợi ý theo giá và cá nhân hóa.</p><h3>Trải nghiệm nghiên cứu minh bạch</h3><p>Ở chế độ demo, chọn một trong 8 hồ sơ, xem sản phẩm, rồi bật MUSE Lab để kiểm tra raw ID, lịch sử thực tế, điểm dự đoán và độ trễ của lần chạy. Khi model không khả dụng, ứng dụng công khai trạng thái fallback.</p><p>Tên tiếng Việt, giá, ngành hàng và ảnh minh họa không phải metadata gốc Taobao. Vì vậy thứ hạng theo checkpoint phản ánh raw ID và SCL gốc; chưa thể dùng demo này để kết luận hiệu quả trên hàng hóa tiếng Việt.</p><p><a href="https://github.com/alimama-tech/MUSE" target="_blank" rel="noopener">Mã nguồn MUSE chính thức ↗</a></p></div>`,true);}
async function handleAction(action,el){
  const id=Number(el?.dataset.id);
  switch(action){
    case'home':case'catalog':case'cart':case'checkout':case'account':case'orders':case'addresses':case'vouchers':case'wishlist':case'notifications':case'password':navigate(action);break;
    case'login':openAuth();break;
    case'retry':await renderRoute();break;
    case'close-modal':closeModal();break;
    case'product':await openProduct(id);break;
    case'demo-login':await loginDemo(id);break;
    case'logout':await post('/auth/logout');state.debugInfo=null;await refreshUser();navigate('home');toast('Đã đăng xuất.');break;
    case'hero':state.hero=Number(el.dataset.index);$('#hero').innerHTML=heroHTML();hydrate();break;
    case'flash':navigate('catalog',{sort:'discount'});break;
    case'home-more':state.homeLimit=Math.min(60,state.homeLimit+12);await refreshHomeRecommendations();if(state.homeLimit===60)el.hidden=true;break;
    case'muse-info':museInfo();break;
    case'favorite':if(requireLogin()){const result=await put('/account/wishlist/'+id);if(result.saved)state.wishlist.add(id);else state.wishlist.delete(id);document.querySelectorAll(`.heart-button[data-id="${id}"]`).forEach(b=>{b.classList.toggle('saved',result.saved);b.setAttribute('aria-label',result.saved?'Bỏ yêu thích':'Yêu thích sản phẩm');});toast(result.saved?'Đã lưu vào sản phẩm yêu thích.':'Đã bỏ khỏi yêu thích.');if(state.route==='wishlist')await renderRoute();}break;
    case'detail-minus':case'detail-plus':{const input=$('#detail-quantity');input.value=Math.max(1,Math.min(Math.min(state.selectedProduct.stock,99),Number(input.value)+(action==='detail-plus'?1:-1)));break;}
    case'add-product':await addProduct();break;
    case'buy-product':await addProduct(true);break;
    case'cart-minus':case'cart-plus':{const item=state.cart.find(x=>x.cart_item_id===id);await put('/cart/'+id,{quantity:item.quantity+(action==='cart-plus'?1:-1),is_selected:!!item.is_selected});await renderRoute();break;}
    case'cart-remove':await api('/cart/'+id,{method:'DELETE'});await renderRoute();toast('Đã xóa khỏi giỏ hàng.');break;
    case'place-order':await placeOrder();break;
    case'clear-filter':navigate('catalog');break;
    case'new-address':await openAddress();break;
    case'edit-address':await openAddress(id);break;
    case'delete-address':await confirmAction('Xóa địa chỉ?','Bạn có thể thêm lại địa chỉ này bất kỳ lúc nào.','confirm-delete-address',id);break;
    case'confirm-delete-address':await api('/account/addresses/'+id,{method:'DELETE'});closeModal();await renderRoute();toast('Đã xóa địa chỉ.');break;
    case'claim-voucher':await post('/vouchers/'+id+'/claim');await renderRoute();toast('Đã lưu voucher vào kho.');break;
    case'read-notifications':await post('/account/notifications/read');await refreshUser();await renderRoute();break;
    case'cancel-order':await confirmAction('Hủy đơn hàng?','Tiền ví demo, Xu và voucher sẽ được hoàn lại nếu đã sử dụng.','confirm-cancel-order',id);break;
    case'confirm-cancel-order':await post('/orders/'+id+'/cancel');closeModal();await refreshUser();await renderRoute();toast('Đã hủy đơn và hoàn lại quyền lợi.');break;
    case'advance-order':await post('/orders/'+id+'/demo-advance');await refreshUser();await renderRoute();toast('Đã cập nhật trạng thái mô phỏng.');break;
    case'reorder':{const order=state.orders.find(o=>o.id===id);for(const item of order.items)await post('/cart',{product_id:item.product_id,quantity:item.quantity});await refreshUser();navigate('cart');toast('Đã thêm các sản phẩm vào giỏ.');break;}
    case'review':{const order=state.orders.find(o=>o.id===id);openModal('Chia sẻ trải nghiệm của bạn',`<form id="review-form"><div class="field"><label for="review-product">Sản phẩm</label><select id="review-product" name="product_id">${order.items.map(i=>`<option value="${i.product_id}">${e(nameOf(i.product_name))}</option>`).join('')}</select></div><div class="field"><label for="review-rating">Đánh giá</label><select id="review-rating" name="rating">${[5,4,3,2,1].map(r=>`<option value="${r}">${'★'.repeat(r)} (${r}/5)</option>`).join('')}</select></div><div class="field"><label for="review-content">Nội dung đánh giá</label><textarea id="review-content" name="content" required minlength="10" maxlength="1000" placeholder="Điều bạn yêu thích về sản phẩm này…"></textarea></div><p id="form-error" class="error-text"></p><button class="primary" type="submit">Gửi đánh giá</button></form>`,true);break;}
    case'history':{const rows=await api('/recommendations/history?limit=1000');openModal('Chuỗi hành vi · 1.000 tương tác gần nhất',`<p class="page-subtitle">${rows.length} bản ghi · imported_click: dữ liệu test Taobao-MM · click / add_to_cart / purchase: tương tác trên web. Danh mục demo chỉ ánh xạ được một phần lịch sử.</p><div class="history-list">${rows.map((h,i)=>`<div class="history-row"><span>${i+1}</span><div><code>${e(h.raw_item_id)}</code><br>${e(h.product_name?nameOf(h.product_name):'Sản phẩm Taobao ngoài danh mục demo')}</div><small>${e(h.action_type)}<br>${e(date(h.created_at))}</small></div>`).join('')}</div>`);break;}
    case'help':openModal('Mua sắm dễ dàng hơn',`<div class="help-prose"><h3>Đặt hàng</h3><p>Chọn sản phẩm → thêm vào giỏ → chọn địa chỉ, voucher và phương thức thanh toán → kiểm tra tổng tiền → đặt hàng.</p><h3>Vận chuyển & ưu đãi</h3><p>Cước vận chuyển demo được tính theo tỉnh nhận hàng và số shop. Miễn cước tiêu chuẩn cho đơn từ 150.000₫ khi tất cả sản phẩm hỗ trợ Freeship. Mỗi đơn dùng một voucher và tối đa 25.000 Xu.</p><h3>Quản lý đơn hàng</h3><p>Vào Đơn mua để theo dõi và hủy đơn đang chờ xác nhận. Đánh giá sản phẩm sau khi đơn được đánh dấu đã giao. Các thao tác mô phỏng trạng thái chỉ có trong chế độ demo.</p><h3>Trải nghiệm mô hình</h3><p>Chọn hồ sơ thử nghiệm trên thanh phía trên, tương tác với sản phẩm và bật MUSE Lab để xem dữ liệu suy luận.</p></div>`,true);break;
    case'about':openModal('Shopee MUSE · Không gian nghiên cứu',`<div class="help-prose"><p>Ứng dụng tập trung vào trải nghiệm khách mua hàng và trình diễn mô hình gợi ý Alibaba MUSE. Kênh bán hàng và ứng dụng di động chưa được triển khai trong phiên bản này.</p><h3>Về bản demo</h3><p>Đây là đồ án nghiên cứu độc lập, không liên kết với Shopee. Gian hàng, ưu đãi, tồn kho, đánh giá mẫu, ví và giao nhận phục vụ minh họa.</p><p>Những thao tác bạn thực hiện được lưu thật trong cơ sở dữ liệu của ứng dụng.</p></div>`,true);break;
  }
}
document.addEventListener('click',async event=>{
  const target=event.target.closest('button,a');if(!target||target.disabled)return;
  try{
    if(target.dataset.action){event.preventDefault();await handleAction(target.dataset.action,target);}
    else if(target.dataset.search!=null){event.preventDefault();$('#search').value=target.dataset.search;navigate('catalog',{q:target.dataset.search});}
    else if(target.dataset.category){event.preventDefault();navigate('catalog',{category_id:target.dataset.category});}
    else if(target.dataset.sort){updateCatalogParams({sort:target.dataset.sort});}
    else if(target.dataset.page){updateCatalogParams({page:target.dataset.page});}
    else if(target.dataset.auth){openAuth(target.dataset.auth);}
    else if(target.dataset.tab){state.orderTab=target.dataset.tab;await renderRoute();}
    else if(target.dataset.shop){navigate('catalog',{q:target.dataset.shop});}
  }catch(error){toast(error.message,true);}
});
document.addEventListener('change',async event=>{
  const el=event.target;
  try{
    if(el.id==='profile-switch'&&el.value)await loginDemo(el.value);
    else if(el.id==='debug-toggle'){state.debug=el.checked;localStorage.setItem('muse_debug',String(state.debug));await refreshDebug();if(state.route==='home')await refreshHomeRecommendations();else if(state.route==='catalog'||state.route==='wishlist')await renderRoute();}
    else if(el.id==='price-sort'&&el.value)updateCatalogParams({sort:el.value});
    else if(el.dataset.cartSelect){const item=state.cart.find(i=>i.cart_item_id===Number(el.dataset.cartSelect));await put('/cart/'+item.cart_item_id,{quantity:item.quantity,is_selected:el.checked});await renderRoute();}
    else if(el.id==='cart-select-all'){for(const item of state.cart)await put('/cart/'+item.cart_item_id,{quantity:item.quantity,is_selected:el.checked});await renderRoute();}
    else if(el.name==='checkout_address'||el.id==='checkout-voucher'||el.id==='checkout-coins'||el.name==='payment'){
      if(el.name==='checkout_address')state.checkout.address_id=Number(el.value);if(el.id==='checkout-voucher')state.checkout.voucher_code=el.value;if(el.id==='checkout-coins')state.checkout.use_coins=el.checked;if(el.name==='payment')state.checkout.payment_method=el.value;
      state.checkoutKey=crypto.randomUUID();await updateQuote();
    }
  }catch(error){toast(error.message,true);}
});
document.addEventListener('submit',async event=>{
  const form=event.target;event.preventDefault();const data=Object.fromEntries(new FormData(form));const button=form.querySelector('button[type=submit]');if(button)button.disabled=true;
  try{
    if(form.id==='search-form'){navigate('catalog',{q:$('#search').value.trim()});}
    else if(form.id==='filter-form'){if(data.max_price&&Number(data.max_price)<Number(data.min_price))throw new Error('Giá tối đa cần lớn hơn giá tối thiểu.');updateCatalogParams(data);}
    else if(form.id==='auth-form'){
      if(state.authMode==='login'||state.authMode==='register'){await post('/auth/'+state.authMode,data);state.checkout.address_id=null;state.checkoutKey=null;await refreshUser();closeModal();toast('Chào mừng '+nameOf(state.user.full_name)+'!');await renderRoute();}
      else if(state.authMode==='forgot'){const result=await post('/auth/forgot-password',data);state.challenge=result.challenge_id;openAuth('reset');}
      else{await post('/auth/reset-password',{...data,challenge_id:state.challenge});toast('Đã đặt lại mật khẩu. Vui lòng đăng nhập.');openAuth('login');}
    }
    else if(form.id==='profile-form'){await put('/account/profile',{...data,birth_year:data.birth_year?Number(data.birth_year):null});await refreshUser();toast('Đã lưu thông tin tài khoản.');}
    else if(form.id==='address-form'){const body={...data,province_id:Number(data.province_id),is_default:new FormData(form).has('is_default')};if(form.dataset.id)await put('/account/addresses/'+form.dataset.id,body);else await post('/account/addresses',body);closeModal();toast('Đã lưu địa chỉ nhận hàng.');await renderRoute();}
    else if(form.id==='password-form'){if(data.new_password!==data.confirm_password)throw new Error('Mật khẩu xác nhận chưa khớp.');await post('/auth/password',data);form.reset();toast('Đã cập nhật mật khẩu.');}
    else if(form.id==='review-form'){await post('/products/'+data.product_id+'/reviews',{rating:Number(data.rating),content:data.content});closeModal();toast('Cảm ơn bạn đã chia sẻ đánh giá.');}
  }catch(error){const target=form.querySelector('#form-error');if(target)target.textContent=error.message;else toast(error.message,true);}
  finally{if(button)button.disabled=false;}
});
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
$('#modal').addEventListener('cancel',()=>{state.modalVersion++;});
window.addEventListener('hashchange',renderRoute);
setInterval(updateCountdown,1000);
setInterval(()=>{if(state.route==='home'&&!$('#modal').open&&$('#hero')){state.hero=(state.hero+1)%heroes.length;$('#hero').innerHTML=heroHTML();placeholder($('#hero'));}},9000);
async function init(){try{
  const [catalog,current]=await Promise.all([api('/catalog'),api('/auth/me')]);state.categories=catalog.categories;state.provinces=catalog.provinces;state.user=current.user;state.demo=current.demo_mode;
  if(state.demo){state.profiles=await api('/auth/demo-profiles');$('#profile-switch').innerHTML='<option value="">Chọn hồ sơ mua sắm</option>'+state.profiles.map(p=>`<option value="${p.id}">${e(nameOf(p.full_name))} · ${e(p.member_tier)}</option>`).join('');}
  await refreshUser();hydrate();await renderRoute();
}catch(error){appHTML(`<div class="container page">${empty('Chưa kết nối được cửa hàng',error.message,'retry','Thử lại','return')}</div>`);}}
init();
